}

"use client"

import { useId } from "react"

import { SearchIcon } from "lucide-react"

import { Input } from "@/components/ui/input"
import { Label } from "@/components/ui/label"
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue
} from "@/components/ui/select"
import { ALL_CATEGORIES } from "@/features/products/constants/products.constants"
import { useCategories } from "@/features/products/hooks/use-categories"
import { productSortSchema } from "@/features/products/schemas/product.schema"
import type { ProductCategory, ProductSort } from "@/features/products/schemas/product.schema"
import * as m from "@/paraglide/messages"

type ProductListToolbarProps = {
  q: string
  /** Empty while a search runs, because a search covers every category. */
  category: string
  sort: ProductSort
  initialCategories?: ProductCategory[] | null
  /** When the server fetched `initialCategories`. */
  categoriesUpdatedAt?: number
  onSearch: (value: string) => void
  onCategoryChange: (category: string) => void
  onSortChange: (sort: ProductSort) => void
}

export function ProductListToolbar({
  q,
  category,
  sort,
  initialCategories,
  categoriesUpdatedAt,
  onSearch,
  onCategoryChange,
  onSortChange
}: ProductListToolbarProps) {
  const searchId = useId()
  const categories = useCategories(initialCategories, categoriesUpdatedAt)
  const sortLabels: Record<ProductSort, string> = {
    featured: m.products_sort_featured(),
    "price-asc": m.products_sort_price_asc(),
    "price-desc": m.products_sort_price_desc(),
    rating: m.products_sort_rating(),
    discount: m.products_sort_discount(),
    title: m.products_sort_title()
  }
  const sortItems = productSortSchema.options.map((value) => ({ value, label: sortLabels[value] }))
  const categoryItems = [
    { value: ALL_CATEGORIES, label: m.products_all_categories() },
    ...(categories.data ?? []).map(({ slug, name }) => ({ value: slug, label: name }))
  ]

  return (
    <div className="flex flex-col gap-2 sm:flex-row">
      <div className="relative min-w-0 flex-1">
        <Label htmlFor={searchId} className="sr-only">
          {m.products_search_label()}
        </Label>
        <SearchIcon
          aria-hidden
          className="absolute top-1/2 left-3 size-4 -translate-y-1/2 text-muted-foreground"
        />
        <Input
          id={searchId}
          type="search"
          placeholder={m.products_search_label()}
          className="pl-9"
          value={q}
          onChange={(event) => onSearch(event.target.value)}
        />
      </div>

      <Select
        items={categoryItems}
        value={category || ALL_CATEGORIES}
        disabled={categories.isPending}
        onValueChange={(value) => onCategoryChange(!value || value === ALL_CATEGORIES ? "" : value)}
      >
        <SelectTrigger aria-label={m.products_category_label()} className="w-full sm:w-44">
          <SelectValue />
        </SelectTrigger>
        <SelectContent>
          {categoryItems.map((item) => (
            <SelectItem key={item.value} value={item.value}>
              {item.label}
            </SelectItem>
          ))}
        </SelectContent>
      </Select>

      <Select
        items={sortItems}
        value={sort}
        onValueChange={(value) => {
          const parsed = productSortSchema.safeParse(value)
          if (parsed.success) onSortChange(parsed.data)
        }}
      >
        <SelectTrigger aria-label={m.products_sort_label()} className="w-full sm:w-44">
          <SelectValue />
        </SelectTrigger>
        <SelectContent>
          {sortItems.map((item) => (
            <SelectItem key={item.value} value={item.value}>
              {item.label}
            </SelectItem>
          ))}
        </SelectContent>
      </Select>
    </div>
  )
}

import type { MouseEvent } from "react"

import { cn } from "cn"

import {
  Pagination,
  PaginationContent,
  PaginationItem,
  PaginationNext,
  PaginationPrevious
} from "@/components/ui/pagination"
import * as m from "@/paraglide/messages"

type ProductPaginationProps = {
  page: number
  totalPages: number
  /** A real link to the page, so it opens without JavaScript and search engines follow it. */
  getPageHref: (page: number) => string
  onPageChange: (page: number) => void
}

const DISABLED_LINK = "pointer-events-none opacity-50"

/** A click that should open a new tab or window instead, which the link must leave alone. */
function isModifiedClick(event: MouseEvent<HTMLAnchorElement>) {
  return event.button !== 0 || event.metaKey || event.ctrlKey || event.shiftKey || event.altKey
}

export function ProductPagination({
  page,
  totalPages,
  getPageHref,
  onPageChange
}: ProductPaginationProps) {
  const isFirst = page <= 1
  const isLast = page >= totalPages
  // The link goes to the page without JavaScript; with it, the list changes in place.
  const go = (event: MouseEvent<HTMLAnchorElement>, target: number, isDisabled: boolean) => {
    if (isModifiedClick(event) && !isDisabled) return
    event.preventDefault()
    if (!isDisabled) onPageChange(target)
  }

  return (
    <Pagination aria-label={m.products_pagination_label()}>
      <PaginationContent className="w-full justify-between">
        <PaginationItem>
          <PaginationPrevious
            href={isFirst ? undefined : getPageHref(page - 1)}
            text={m.products_previous()}
            aria-label={m.products_previous_page()}
            aria-disabled={isFirst}
            tabIndex={isFirst ? -1 : undefined}
            className={cn(isFirst && DISABLED_LINK)}
            onClick={(event) => go(event, page - 1, isFirst)}
          />
        </PaginationItem>
        <PaginationItem className="text-sm text-muted-foreground">
          <p className="text-center tabular-nums">{m.products_page_status({ page, totalPages })}</p>
        </PaginationItem>
        <PaginationItem>
          <PaginationNext
            href={isLast ? undefined : getPageHref(page + 1)}
            text={m.products_next()}
            aria-label={m.products_next_page()}
            aria-disabled={isLast}
            tabIndex={isLast ? -1 : undefined}
            className={cn(isLast && DISABLED_LINK)}
            onClick={(event) => go(event, page + 1, isLast)}
          />
        </PaginationItem>
      </PaginationContent>
    </Pagination>
  )
}

