/**
 * The filters and the page live in the URL, changed on the client without a document load. `q`
 * follows every keystroke for the input, while `query` and the URL wait for a pause, so typing does
 * not send a request per letter; the page goes back to 1 together with that search, not before it.
 * An emptied search, like Back and Forward, applies at once. The hook reads the current route, so
 * the module works on whichever page renders it.
 */
export function useProductListParams() {
  const filters = productListSearchSchema.parse(useSearch({ strict: false }))
  const { pathname } = useLocation()
  const navigate = useNavigate()
  // What was typed but is not in the URL yet. Without it, the input follows the URL, as on Back.
  const [draft, setDraft] = useState<string | null>(null)

  // useDebounceCallback starts a new timer when its function changes, so this one must be stable.
  const commit = useCallback(
    async (value: string) => {
      await navigate({
        to: ".",
        search: (prev) => ({ ...prev, q: value, page: 1 }),
        replace: true,
        resetScroll: false
      })
      setDraft((current) => (current === value ? null : current))
    },
    [navigate]
  )
  const commitSearch = useDebounceCallback(commit, SEARCH_DEBOUNCE_MS)

  // Leaving the page must not run a pending search, which would navigate back to it.
  useEffect(() => commitSearch.cancel, [commitSearch])

  const navigateTo = (search: Partial<typeof filters>) =>
    navigate({ to: ".", search: (prev) => ({ ...prev, ...search }), resetScroll: false })
  // A filter replaces a search still being typed.
  const push = (search: Partial<typeof filters>) => {
    commitSearch.cancel()
    setDraft(null)
    return navigateTo(search)
  }

  return {
    q: draft ?? filters.q,
    query: filters.q,
    category: filters.category,
    sort: filters.sort,
    page: filters.page,
    getPageHref: (target: number) => `${pathname}${toListSearch({ ...filters, page: target })}`,
    setPage: (target: number) => navigateTo({ page: target }),
    setSearch: (value: string) => {
      if (value.trim()) {
        setDraft(value)
        commitSearch(value)
        return
      }
      commitSearch.cancel()
      setDraft(null)
      void navigate({
        to: ".",
        search: (prev) => ({ ...prev, q: "", page: 1 }),
        replace: true,
        resetScroll: false
      })
    },
    // A search covers every category, so picking one ends the search.
    setCategory: (value: string) => push({ category: value, q: "", page: 1 }),
    setSort: (value: ProductSort) => push({ sort: value, page: 1 }),
    clearFilters: () => push({ q: "", category: "", page: 1 })
  }
}

"use client"

import { useQuery, useQueryClient } from "@tanstack/react-query"
import type { QueryClient } from "@tanstack/react-query"

import { productQueryOptions } from "@/features/products/api/product.queries"
import type { InitialProduct } from "@/features/products/api/product.queries"
import { productKeys } from "@/features/products/api/query-keys"
import { useServerData } from "@/features/products/hooks/use-server-data"
import type {
  Product,
  ProductDetails,
  ProductsPage
} from "@/features/products/schemas/product.schema"

/** The card's fields, with the rest empty until the product arrives. */
function toPreview(product: Product): ProductDetails {
  return {
    ...product,
    description: "",
    images: [product.thumbnail],
    tags: [],
    sku: "",
    stock: 0,
    dimensions: { width: 0, height: 0, depth: 0 },
    warrantyInformation: "",
    shippingInformation: "",
    returnPolicy: "",
    minimumOrderQuantity: 0,
    reviews: []
  }
}

function findInLists(queryClient: QueryClient, id: number) {
  const lists = queryClient.getQueriesData<ProductsPage>({ queryKey: productKeys.lists() })
  for (const [, data] of lists) {
    const product = data?.products.find((item) => item.id === id)
    if (product) return toPreview(product)
  }
  return undefined
}

/**
 * Coming from the list, the card already holds the title, image and price, so those show at once
 * while the rest loads. `initial` is what the server fetched for the page, when it did.
 */
export function useProduct(id: number | null, initial?: InitialProduct) {
  const queryClient = useQueryClient()
  const options = productQueryOptions(id ?? 0)
  const product = initial?.product
  useServerData(options.queryKey, product && product.id === id ? product : null, initial?.updatedAt)

  return useQuery({
    ...options,
    enabled: id !== null,
    placeholderData: () => (id === null ? undefined : findInLists(queryClient, id))
  })
}

"use client"

import { hashKey, useQuery } from "@tanstack/react-query"

import { productsQueryOptions } from "@/features/products/api/product.queries"
import type { InitialProducts } from "@/features/products/api/product.queries"
import { useServerData } from "@/features/products/hooks/use-server-data"
import type { ProductsFilters } from "@/features/products/schemas/product-list-params.schema"

/**
 * The server's page fills the cache only for the filters and the page it was fetched with. Every
 * other page, filter or sort is fetched here, on the client.
 */
export function useProducts(filters: ProductsFilters, initial?: InitialProducts | null) {
  const options = productsQueryOptions(filters)
  const isInitial = initial ? hashKey(initial.queryKey) === hashKey(options.queryKey) : false
  useServerData(options.queryKey, isInitial ? initial?.data : null, initial?.updatedAt)

  return useQuery(options)
}

"use client"

import { useState } from "react"

import { useQueryClient } from "@tanstack/react-query"
import type { QueryKey } from "@tanstack/react-query"

/**
 * Puts what the server fetched into the cache, unless the cache already holds something newer.
 * `initialData` alone is ignored once the cache has the key, so coming back to a page would show
 * the older client copy and fetch it again.
 */
export function useServerData<T>(
  queryKey: QueryKey,
  data: T | null | undefined,
  updatedAt: number | undefined
) {
  const queryClient = useQueryClient()

  // Once per mount, before the query that reads the key subscribes, so it starts from this copy.
  useState(() => {
    if (data === null || data === undefined || updatedAt === undefined) return
    const state = queryClient.getQueryState(queryKey)
    if (!state || state.dataUpdatedAt < updatedAt) {
      queryClient.setQueryData(queryKey, data, { updatedAt })
    }
  })
}

import { stripSearchParams } from "@tanstack/react-router"
import { z } from "zod"

import { MAX_PAGE } from "@/features/products/constants/products.constants"
import { productSortSchema } from "@/features/products/schemas/product.schema"

// The router parses `?q=123` into a number and `?q=true` into a boolean, so those become text again.
const text = z.union([z.string(), z.number(), z.boolean()]).transform(String)

/**
 * Anything invalid in a shared link falls back to its default. The category slug becomes part of
 * the request path; it is encoded there, which leaves only `.` and `..` able to change the path.
 */
export const productListSearchSchema = z.object({
  q: text.default("").catch(""),
  category: text
    .refine((value) => value !== "." && value !== "..")
    .default("")
    .catch(""),
  sort: productSortSchema.default("featured").catch("featured"),
  // A whole number counts however it is written (`10`, `010`, `1e1`): the router has read most of
  // them as a number already, and the rest are text. Anything else is the first page. A number past
  // the safe range still counts, and the cap brings it back.
  page: z
    .union([z.number(), z.string().transform(Number)])
    .pipe(z.number().positive().refine(Number.isInteger))
    .transform((value) => Math.min(value, MAX_PAGE))
    .default(1)
    .catch(1)
})

/** What the list shows: the filters and the page. */
export type ProductsFilters = z.infer<typeof productListSearchSchema>

export const PRODUCT_LIST_DEFAULTS: ProductsFilters = {
  q: "",
  category: "",
  sort: "featured",
  page: 1
}

/** Spread into the list's route. Default values stay out of the URL. */
export const productListRouteSearch = {
  validateSearch: productListSearchSchema,
  search: { middlewares: [stripSearchParams<ProductsFilters>(PRODUCT_LIST_DEFAULTS)] }
}

/** `?category=beauty&page=2` for a link, without the defaults, as the router writes it. */
export function toListSearch(filters: ProductsFilters) {
  const params = new URLSearchParams()
  for (const [key, value] of Object.entries(filters)) {
    if (value !== PRODUCT_LIST_DEFAULTS[key as keyof ProductsFilters])
      params.set(key, String(value))
  }
  const search = params.toString()
  return search ? `?${search}` : ""
}

import { createFileRoute } from "@tanstack/react-router"

import { siteConfig } from "@/config/site.config"

import { hreflangLinks, localizedUrl } from "@/helpers/localized-url"

import { loadProduct } from "@/features/products/api/load-products"
import { ProductDetail } from "@/features/products/components/ProductDetail"
import { ProductDetailSkeleton } from "@/features/products/components/ProductDetailSkeleton"
import { ProductNotFound } from "@/features/products/components/ProductNotFound"
import { getProductHref } from "@/features/products/helpers/product-href"
import {
  getProductImage,
  getProductJsonLd,
  toJsonLd
} from "@/features/products/helpers/product-seo"
import { getShareMeta } from "@/features/products/helpers/share-meta"
import * as m from "@/paraglide/messages"
import { getLocale } from "@/paraglide/runtime"

export const Route = createFileRoute("/{-$lang}/products/$id")({
  /**
   * The server fetches the product, so its HTML already has it, and a product that does not exist
   * answers with a real 404. A request that fails otherwise leaves the product to the client.
   */
  loader: ({ context: { queryClient }, params }) => loadProduct(queryClient, params.id),
  head: ({ loaderData: product }) => {
    // A request that failed: the product is left to the client, and so is everything else here.
    if (!product)
      return { meta: [{ title: `${m.products_product_fallback_title()} · ${siteConfig.name}` }] }

    const { title, description } = product
    const url = localizedUrl(getProductHref(product.id), getLocale())

    return {
      meta: [
        { title: `${title} · ${siteConfig.name}` },
        { name: "description", content: description },
        ...getShareMeta({
          title,
          description,
          url,
          image: { url: getProductImage(product), alt: title }
        })
      ],
      links: [{ rel: "canonical", href: url }, ...hreflangLinks(getProductHref(product.id))],
      // Product data for search results.
      scripts: [{ type: "application/ld+json", children: toJsonLd(getProductJsonLd(product, url)) }]
    }
  },
  pendingComponent: () => (
    <main className="mx-auto w-full max-w-4xl flex-1 px-4 py-6 sm:px-6">
      <ProductDetailSkeleton />
    </main>
  ),
  // The loader's `notFound()`: the module's own state, with the way back to the list.
  notFoundComponent: () => (
    <main className="mx-auto w-full max-w-4xl flex-1 px-4 py-6 sm:px-6">
      <ProductNotFound />
    </main>
  ),
  component: ProductPage
})

function ProductPage() {
  return (
    <main className="mx-auto w-full max-w-4xl flex-1 px-4 py-6 sm:px-6">
      <ProductDetail />
    </main>
  )
}

import { createFileRoute } from "@tanstack/react-router"

import { siteConfig } from "@/config/site.config"

import { hreflangLinks, localizedUrl } from "@/helpers/localized-url"

import { loadProductList } from "@/features/products/api/load-products"
import { ProductList } from "@/features/products/components/ProductList"
import { ProductListSkeleton } from "@/features/products/components/ProductListSkeleton"
import { getProductsCanonicalHref } from "@/features/products/helpers/product-href"
import { getProductListFacts, getProductListText } from "@/features/products/helpers/product-seo"
import { getShareMeta } from "@/features/products/helpers/share-meta"
import { productListRouteSearch } from "@/features/products/schemas/product-list-params.schema"
import * as m from "@/paraglide/messages"
import { getLocale } from "@/paraglide/runtime"

export const Route = createFileRoute("/{-$lang}/products/")({
  ...productListRouteSearch,
  loaderDeps: ({ search }) => search,
  /**
   * The server fetches the page the URL asks for, so the first HTML already lists the products. On
   * the client a new page, filter or sort does not wait here: the list keeps the page on screen
   * while the next one loads.
   */
  loader: ({ context: { queryClient }, deps, cause }) =>
    loadProductList(queryClient, deps, { wait: cause !== "stay" }),
  head: ({ match, loaderData }) => {
    const facts = getProductListFacts(match.search, loaderData?.data, loaderData?.categories)
    const { title, description } = getProductListText(facts, {
      title: m.products_title(),
      searchTitle: (query) => m.products_meta_search_title({ query }),
      pageTitle: (base, page) => m.products_meta_page_title({ title: base, page }),
      description: m.products_meta_description(),
      listDescription: (count) => m.products_meta_list_description({ count }),
      categoryDescription: (count, category) =>
        m.products_meta_category_description({ count, category }),
      searchDescription: (count, query) => m.products_meta_search_description({ count, query })
    })
    const href = getProductsCanonicalHref(match.search)
    const url = localizedUrl(href, getLocale())
    const image = facts.image ? { url: facts.image, alt: title } : null

    return {
      meta: [
        { title: `${title} · ${siteConfig.name}` },
        { name: "description", content: description },
        ...getShareMeta({ title, description, url, image }),
        // Search results are not pages of their own; their links are still followed.
        ...(facts.query ? [{ name: "robots", content: "noindex, follow" }] : [])
      ],
      links: [{ rel: "canonical", href: url }, ...hreflangLinks(href)]
    }
  },
  pendingComponent: () => (
    <main className="mx-auto flex w-full max-w-4xl flex-1 flex-col gap-4 px-4 py-6 sm:px-6">
      <ProductListSkeleton />
    </main>
  ),
  component: ProductsPage
})

function ProductsPage() {
  return (
    <main className="mx-auto flex w-full max-w-4xl flex-1 flex-col gap-4 px-4 py-6 sm:px-6">
      <h1 className="text-2xl font-semibold tracking-tight">{m.products_title()}</h1>
      <ProductList />
    </main>
  )
}
